section.programlisting:
// Создаём экземпляр модуля проверки орфографии
SpellChecker checker = new SpellChecker();

// Проверяем текст на русском языке
string text = "Привет мир";
List<string> errors = checker.CheckText(text, Language.Russian);

// Получаем варианты замены для ошибочного слова
List<string> suggestions = checker.GetSuggestions("мир", Language.Russian);

// Создаём менеджер тем
ThemeManager themeManager = new ThemeManager();

// Применяем тёмную тему к главному окну
themeManager.ApplyTheme(mainWindow, Theme.Dark);

// Получаем текущую активную тему
Theme current = themeManager.GetCurrentTheme();

// Создаём модуль поиска и замены
SearchReplace searchReplace = new SearchReplace(textArea);

// Находим следующее вхождение без учёта регистра
bool found = searchReplace.FindNext("привет", matchCase: false);

// Заменяем все вхождения строки
int count = searchReplace.ReplaceAll("привет", "здравствуйте", matchCase: false);
